-- R8b (2026-07-24) -- make the MatchMatrix methodology/about prose describe the
-- REAL tool. Follows R8 (MatchMatrix v2). Re-reading the ~10 tool-scope claims
-- against v2 found most now TRUE, but the methodology page and two about-page
-- differentiators describe an INVENTED system (bug 043 class, process flavour):
-- a weighted distance metric with six scoring dimensions, adjustable/saveable
-- weighting vectors, cycle-time scoring in ms, spec "normalization" to
-- "IEC 60529-aligned test conditions" with a fabricated 120 N -> 94 N example
-- (IEC 60529 is the IP-rating standard -- not a force test standard), third-party
-- /peer-reviewed test data, manufacturer "enrolment", hard-limit override, and
-- "identical criteria" across technologies. None of that exists, and NO honest
-- tool extension can make it exist -- it would require inventing data and
-- processes, which is the very thing this workstream prohibits. v2 is genuinely
-- auditable in a way the fiction never was (every requirement figure prints its
-- formula), so the honest text is also the stronger text.
--
-- Edits (kept entries byte-identical; only fabricated ones rewritten):
--   about/differentiators.features: [0] "same criteria" -> per-technology
--     criteria, drop cycle-time/payload-to-weight from the compared list;
--     [1] weighting fiction -> printed-formula auditability; [2] "Normalized
--     Specs" INVERTED to "Published Specs, Reproduced Verbatim" (the site's own
--     actual policy, stated elsewhere) and the fake 120->94 N example deleted;
--     [4] false "no re-entry between tools" claim dropped; [6] third-party/
--     peer-reviewed data claim -> requirement-side realism (mu-trap, ferrous
--     gate, surface notes). [3] (no commercial relationships -- policy) and
--     [5] (catalog depth -- now true) kept verbatim.
--   matchmatrix-methodology/generic-text-block.content: full rewrite describing
--     v2's actual mechanics (three requirement figures, per-technology criteria,
--     breach vs marginal vs insufficient-data, verbatim specs, hand-recomputable).
--   matchmatrix-methodology/faq.questions: answers 1-8 and 10 rewritten to the
--     real system (ranking = verdict class + headroom, no weights, inputs are
--     the adjustment, no override fiction, real cobot lines named); question 9
--     (index depth) kept verbatim -- it is true and now traceable.
--
-- Apply:  kubectl -n ai-persona-system exec -i postgres-clients-0 -- \
--           psql -U clients_user -d clients_db < THIS_FILE

\set site '00ff3af5-dad8-4770-9f70-3edc267a3c92'

BEGIN;

UPDATE page_components pc
   SET content_data = jsonb_set(content_data, '{features}', $r8b$[{"name": "Cross-Technology Comparison in a Single Query", "description": "Most gripper catalogs are organized by manufacturer or actuation type, which means you compare pneumatic against pneumatic and miss the possibility that a vacuum or magnetic solution fits your payload and handling constraints better. Robot-Hands.com indexes pneumatic, electric, vacuum, magnetic, soft-robotic, and adhesive grippers under a consistent parameter schema. One MatchMatrix query tests candidates across all six actuation technologies against the same application requirement, each technology assessed on the criteria its manufacturer publishes. You see the trade-offs — grip force, stroke, payload rating, IP rating — side by side, not across six separate supplier websites."}, {"name": "MatchMatrix Scoring Is Documented and Auditable", "description": "MatchMatrix is not a recommendation algorithm with undisclosed weighting — there is no weighting at all. Every requirement figure is printed with the formula and the numbers that produced it, and every criterion on every result card shows the published figure it was tested against and the margin or shortfall. If a gripper fails, you can trace exactly why — which input parameter drove the requirement and which published figure fell short. The output is a shortlist, not a verdict."}, {"name": "Published Specs, Reproduced Verbatim", "description": "Manufacturer datasheets state performance under conditions that vary between suppliers. Robot-Hands.com does not normalise or adjust published figures — every specification is reproduced verbatim as its manufacturer publishes it, with a source link and a last-verified date on the catalog entry. Where a figure is not published, the entry says so, and MatchMatrix treats it as a gap rather than assuming a value. Where a published rating rests on assumptions your application violates — a payload rating that quietly assumes high-friction fingers — the tool says so explicitly rather than letting two published figures silently contradict each other."}, {"name": "No Commercial Relationships With Listed Manufacturers", "description": "Robot-Hands.com does not accept placement fees, sponsored listings, or ranking adjustments from gripper manufacturers. No manufacturer pays to appear higher in MatchMatrix results or in catalog search returns. Catalog coverage is determined by specification completeness and data verifiability, not commercial agreement. This is stated explicitly because the alternative — a platform where ranking is purchasable — is common in industrial component discovery and produces selection bias that costs engineers time and procurement money."}, {"name": "Integrated Specification Workflow", "description": "The platform is built around the sequential decision process gripper selection actually follows: define application constraints → review the catalog across actuation types → run payload and cycle-time calculations with the built-in calculators → run MatchMatrix against the full index → take the ranked shortlist with per-criterion pass/fail results into review or procurement. Each tool's output tells you what to check next."}, {"name": "Catalog Depth Across Manufacturers and Technologies", "description": "Catalog coverage spans multiple actuation technologies and manufacturers, with entries verified against primary source documentation. Each entry records the data source and last-verified date. Coverage is ongoing — new models are indexed as manufacturer documentation becomes available and passes the normalization review. Catalog depth statistics are published on the platform and updated as the index grows, so you can assess coverage against your own shortlisting needs before running a query."}, {"name": "Performance Criteria Grounded in Real-World Conditions", "description": "Datasheet performance figures describe what a gripper can do under the manufacturer's stated conditions. Application performance depends on surface friction, acceleration, safety margin and duty cycle — which is why MatchMatrix computes your requirement from those variables rather than comparing headline numbers. Its results flag the real-world traps explicitly: payload ratings that assume high-friction fingers, holding force that applies to ferromagnetic material only, adhesion that needs clean, smooth, dry surfaces. Every figure remains manufacturer-published; the realism comes from what your requirement is computed against, not from adjusted data."}]$r8b$::jsonb),
       updated_at = now()
 WHERE pc.page_id = (SELECT id FROM pages WHERE site_id = :'site' AND name='about')
   AND pc.slot_name = 'differentiators';

UPDATE page_components pc
   SET content_data = jsonb_set(content_data, '{content}', to_jsonb($r8b$<p>A MatchMatrix result is not a rating. It is a set of explicit pass/fail tests — a comparison of each gripper's published specification against the requirement your application defines. Every result is decomposable: each criterion is shown with the published figure it was tested against, the margin or shortfall, and the requirement it had to meet. Nothing is hidden, and nothing is averaged in ways that obscure a critical mismatch.</p><p>One application, three requirement figures. Manufacturers across the six actuation technologies publish three different kinds of capacity figure, so MatchMatrix derives all three from your inputs: a <strong>friction-grip force</strong> for jaw grippers (F = m × a × S ÷ (μ × n)), a <strong>direct holding force</strong> for the magnetic gripper (F = m × a × S), and a <strong>dynamics-adjusted equivalent payload</strong> for vacuum, adhesive and soft grippers (m′ = m × a × S ÷ g). Each gripper is tested against the figure that matches what its manufacturer publishes — a payload rating earned at rest is not silently credited with surviving your acceleration and safety factor.</p><p>The criteria map to each technology as follows. Jaw grippers — electric and pneumatic — are tested on gripping force, jaw travel, rated payload (where published and requested) and IP rating (where required). The magnetic gripper is tested on workpiece material — ferromagnetic only — and on its published holding force, using the lower, friction-ring figure. Vacuum and adhesive grippers are tested on their published payload rating; the soft gripper also on its 11–118 mm cup range. A vacuum gripper is not scored on jaw stroke — it has no jaws — and it is not scored on figures its manufacturer does not publish.</p><p>A failed hard constraint is a constraint breach, not a low score: it produces a <strong>No match</strong> verdict outright. A gripper that passes with less than 25% margin on its capacity figure is flagged <strong>Marginal</strong>. Where a requested criterion has no published figure, the verdict is <strong>Insufficient data</strong> — the gap is shown, never filled with an assumed value. These are three different things, and MatchMatrix distinguishes them clearly.</p><p>Specification data comes from manufacturer-published datasheets and product pages only, reproduced verbatim. Each catalog entry records its source and a last-verified date. MatchMatrix does not normalise, adjust or interpolate published figures — where a specification is not published, that is stated, and where a published rating rests on assumptions your application violates (a payload rating that quietly assumes high-friction fingers, for instance), the result says so explicitly, with the implied friction coefficient shown.</p><p>Cross-technology comparison is deliberate and load-bearing. Electric and pneumatic parallel-jaw grippers, an electric vacuum gripper, a permanent magnetic gripper, a soft silicone gripper and a gecko-adhesive gripper all run against the same application requirement with technology-appropriate criteria. The criteria adapt; the auditability does not change.</p><p>The formulas, criteria mappings and not-published handling are documented on this page and restated in the tool's own output — every requirement figure is printed with the formula and the numbers that produced it, so any engineer can recompute a MatchMatrix result by hand.</p>$r8b$::text)),
       updated_at = now()
 WHERE pc.page_id = (SELECT id FROM pages WHERE site_id = :'site' AND name='matchmatrix-methodology')
   AND pc.slot_name = 'generic-text-block'
   AND pc.content_data->>'content' LIKE '%six primary dimensions%';

UPDATE page_components pc
   SET content_data = jsonb_set(content_data, '{questions}', $r8b$[{"answer": "MatchMatrix tests gripper suitability against your application across the published parameters: gripping or holding force, jaw travel or grip range, rated payload, IP rating, and — for the magnetic gripper — workpiece material. It does not score cost, lead time, vendor support quality, or regional availability — those are procurement variables outside the scope of an engineering specification tool. The output is a ranked shortlist of the indexed grippers that meet your application constraints, not a purchasing recommendation.", "question": "What exactly does MatchMatrix score, and what does it not score?"}, {"answer": "By verdict class first — Match, then Marginal, then Insufficient data, then No match — and within a class by capacity headroom: the ratio of the gripper's published capacity figure to your requirement. There is no hidden weighting to audit because there is no weighting at all; every figure that determines rank is printed on the result card.", "question": "How are results ranked?"}, {"answer": "MatchMatrix is actuation-neutral in what it indexes and tests: pneumatic, electric, vacuum, magnetic, soft-robotic, and adhesive grippers all run against the same application requirement. The criteria differ by technology because the published figures differ — a vacuum gripper publishes a payload rating, not a gripping force, so it is tested on payload with your dynamics applied. Where an actuation type has a structural advantage for a given application, that advantage emerges from the specification match, not from embedded bias in the assessment.", "question": "Is MatchMatrix technology-neutral, or does it favour certain actuation types?"}, {"answer": "Specification data is sourced from manufacturer technical datasheets and published product documentation. Each catalog entry includes a source link and a last-verified date so you can assess data currency before relying on it for a specification decision. We do not interpolate or estimate values that are not documented — if a parameter is not confirmed from a primary source, it is shown as not published rather than filled with an assumed value.", "question": "Where does the gripper specification data come from, and how current is it?"}, {"answer": "The inputs are the adjustment: safety factor (2 for static handling, 3–4 for dynamic or overhead), peak acceleration, surface material, number of gripping surfaces, minimum IP rating, and whether published payload ratings are checked. Raising the safety factor tightens every technology's requirement at once. There are no weighting profiles to configure because no weighting exists.", "question": "Can I adjust the assessment for my specific application?"}, {"answer": "If a requirement exceeds a gripper's published specification — required force above its rated gripping force, a part outside the soft gripper's cup range, a non-ferromagnetic part on the magnetic gripper — that model receives a FAIL on the criterion and a No match verdict. This is intentional: a gripper operating beyond its published parameters is not a viable specification regardless of how it looks on other criteria. The one relaxation offered is turning off the payload-rating check for jaw grippers, where the force calculation is the primary criterion.", "question": "How does MatchMatrix handle parameters that fall outside a gripper's rated specification?"}, {"answer": "A filter returns everything that clears a threshold. MatchMatrix computes your application's requirement figures, tests every indexed gripper against them criterion by criterion, and shows the margin or shortfall on each — so two grippers that both pass are still distinguishable by headroom, and a gripper that fails is shown with exactly the figure it missed.", "question": "What is the difference between a MatchMatrix score and a simple filter query?"}, {"answer": "Yes. The formulas, the per-technology criteria mappings, and the not-published handling are documented on this page, and every result prints the requirement calculation that produced it — formula, numbers and all. Any engineer can audit a MatchMatrix result by recomputing it by hand.", "question": "Is the MatchMatrix scoring methodology publicly documented?"}, {"answer": "The catalog covers multiple actuation technologies across a broad range of manufacturers. Current index depth — including the number of gripper models, manufacturers represented, and actuation technologies benchmarked — is published on the catalog overview page and updated as new models are added. We prioritise indexing depth across technology categories over comprehensive coverage of any single manufacturer's full product range, to maintain cross-technology comparison utility.", "question": "How many gripper models and manufacturers are currently indexed in the catalog?"}, {"answer": "The catalog includes end-effectors designed for collaborative robot deployments — the OnRobot 2FG7, VG10, Gecko and Soft Gripper lines are cobot tooling — alongside industrial grippers. When running MatchMatrix for a cobot application, make sure your payload and acceleration inputs reflect the cobot's actual TCP payload rating at your intended operating speed, not the maximum rated payload at full extension.", "question": "Can MatchMatrix be used for collaborative robot (cobot) gripper selection as well as industrial robot applications?"}]$r8b$::jsonb),
       updated_at = now()
 WHERE pc.page_id = (SELECT id FROM pages WHERE site_id = :'site' AND name='matchmatrix-methodology')
   AND pc.slot_name = 'faq';

\echo '--- verify: fabrication markers gone, real markers present ---'
SELECT p.name, pc.slot_name,
       (pc.content_data::text ~* 'six-dimension|six primary dimensions|weighting vector|IEC 60529-aligned|seal integrity|identical criteria|94 N') AS still_fabricated,
       (pc.content_data::text ~* 'friction-ring figure|no weighting|reproduced verbatim|recompute') AS has_real
FROM page_components pc JOIN pages p ON p.id=pc.page_id
WHERE p.site_id = :'site'
  AND ((p.name='about' AND pc.slot_name='differentiators')
    OR (p.name='matchmatrix-methodology' AND pc.slot_name IN ('generic-text-block','faq')))
ORDER BY p.name, pc.slot_name;

-- Re-render both pages so the corrections reach the live artefacts.
INSERT INTO site_work_items
  (site_id, source, item_type, severity, summary, status, created_by, pipeline,
   priority, triaged_at, handler_agent, item_key, spec)
SELECT
  p.site_id, 'robot-hands-r8b-methodology-truth', 'page_rerender', 'medium',
  'Rerender ' || p.name || ' -- methodology/about prose corrected to describe the real MatchMatrix v2 (R8b)',
  'triaged', 'session-2026-07-24-robot-hands', 'build',
  20, now(), 'page-rerender',
  'page_rerender_' || p.name || '_r8btruth_' || p.site_id::text,
  jsonb_build_object('domain','robot-hands.com','reason','cta_links_stale',
                     'page_id',p.id,'page_name',p.name,'filename',ltrim(p.url,'/'))
FROM pages p
WHERE p.site_id = :'site' AND p.name IN ('about','matchmatrix-methodology');

\echo '--- queued ---'
SELECT status, handler_agent, count(*) FROM site_work_items
WHERE source='robot-hands-r8b-methodology-truth' GROUP BY 1,2;

COMMIT;
